const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry around Rosetta branch of Nile mouth
  const roiPoint = ee.Geometry.Point([30.4, 31.5]);
  const roi = roiPoint.buffer(5000); // 5km radius buffer

  // 2. Data Acquisition for 1984 (Landsat 5)
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(roi)
    .filterDate('1984-01-01', '1984-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1984 = await col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log("No data for 1984.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Data Acquisition for 2021 (Landsat 8)
  let col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate('2021-01-01', '2021-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2021 = await col2021.size().getInfo();
  console.log(`2021 Images found: ${size2021}`);

  if (size2021 === 0) {
    // Try Landsat 9 as fallback
    col2021 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(roi)
      .filterDate('2021-01-01', '2021-12-31')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size2021_fallback = await col2021.size().getInfo();
    console.log(`2021 Images found (Landsat 9): ${size2021_fallback}`);

    if (size2021_fallback === 0) {
      console.log("No data for 2021.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 4. Cloud masking function for Landsat Collection 2
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);

    const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);

    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);

    const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);

    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  // 5. Calculate NDVI for both years
  function addNDVI(image) {
    const nir = image.select('SR_B4');
    const red = image.select('SR_B3');
    const ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');
    return image.addBands(ndvi);
  }

  function addNDVI_L8(image) {
    const nir = image.select('SR_B5');
    const red = image.select('SR_B4');
    const ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');
    return image.addBands(ndvi);
  }

  const img1984 = col1984.map(maskL5sr).map(addNDVI).median();
  const img2021 = col2021.map(maskL8sr).map(addNDVI_L8).median();

  // 6. Check valid pixels
  const count1984 = await img1984.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2021 = await img2021.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1984 Valid pixels: ${count1984}`);
  console.log(`2021 Valid pixels: ${count2021}`);

  if (count1984 === 0 || count2021 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Calculate mean NDVI
  const ndvi1984 = await img1984.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2021 = await img2021.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1984 Mean NDVI: ${ndvi1984}`);
  console.log(`2021 Mean NDVI: ${ndvi2021}`);

  // 8. Validation & Final Answer
  if (ndvi1984 === null || ndvi2021 === null || isNaN(ndvi1984) || isNaN(ndvi2021)) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (ndvi1984 < -1 || ndvi1984 > 1 || ndvi2021 < -1 || ndvi2021 > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (ndvi1984 > ndvi2021) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
